struct Settings {unsigned steps=64,roughness=2;float tolerance=.2f,fadeIn=.15f,fadeOut=2,strength=1;bool hasColor=false;ImageColorDescription color;};
Settings settings(const ShaderParameters&p){Settings s;for(const auto&[name,v]:p){if(v.size()!=1||!std::isfinite(v[0]))throw std::invalid_argument("Reflection controls require finite scalar values");const float x=v[0];if(name=="MaxSteps"&&x>=1&&x<=512&&std::floor(x)==x)s.steps=unsigned(x);else if(name=="RoughnessQuality"&&x>=0&&x<=3&&std::floor(x)==x)s.roughness=unsigned(x);else if(name=="DepthTolerance"&&x>=.0001f&&x<=1000)s.tolerance=x;else if(name=="FadeIn"&&x>=0&&x<=64)s.fadeIn=x;else if(name=="FadeOut"&&x>=0&&x<=64)s.fadeOut=x;else if(name=="Strength"&&x>=0&&x<=1)s.strength=x;else throw std::invalid_argument("Invalid screen-space reflection control");}return s;}
ImageColorDescription inputColor(const ShaderFrame&f,const Settings&s){return s.hasColor?s.color:describeImageColor(f.color==SpatialColor::HDR?ImageColorSpace::ExtendedSRGB:f.color==SpatialColor::Linear?ImageColorSpace::LinearSRGB:ImageColorSpace::SRGB);}
